def merge_sorted(a: "ListNode | None", b: "ListNode | None") -> "ListNode | None":
    dummy = tail = ListNode()            # tail is the last node of the merged part
    while a is not None and b is not None:
        if a.val <= b.val:
            tail.next = a
            a = a.next
        else:
            tail.next = b
            b = b.next
        tail = tail.next
    tail.next = a if a is not None else b    # one list ran out: the rest is already sorted
    return dummy.next


